import { Effect } from "effect";
import { AuditSink, InventoryClient } from "./contracts.js";

export const stockFor = Effect.fn("Inventory.stockFor")(function* (sku: string) {
  const client = yield* InventoryClient;
  const audit = yield* AuditSink;
  const result = yield* Effect.result(client.lookup(sku));
  if (result._tag === "Failure") {
    yield* audit.record(result.failure);
    return { state: "unknown" as const };
  }
  return { state: "known" as const, units: result.success };
});

import { Context, Effect, Schema } from "effect";

export class InventoryHttpFailure extends Schema.TaggedError<InventoryHttpFailure>()(
  "InventoryHttpFailure",
  { status: Schema.Int, sku: Schema.String },
) {}
export class InventoryTransportFailure extends Schema.TaggedError<InventoryTransportFailure>()(
  "InventoryTransportFailure",
  { message: Schema.String },
) {}
export type InventoryFailure = InventoryHttpFailure | InventoryTransportFailure;

export class InventoryClient extends Context.Service<
  InventoryClient,
  {
    /** Non-2xx responses, including 404 and 500, fail with InventoryHttpFailure. */
    readonly lookup: (sku: string) => Effect.Effect<number, InventoryFailure>;
  }
>()("fiction/InventoryClient") {}

export class AuditSink extends Context.Service<
  AuditSink,
  {
    /** Record unexpected lookup failures. Missing SKU (404) is expected; 500 is not. */
    readonly record: (failure: InventoryFailure) => Effect.Effect<void>;
  }
>()("fiction/AuditSink") {}

