import { Effect } from "effect";
import { AuditSink, InventoryClient } from "./contracts.js";

export const stockFor = Effect.fn("Inventory.stockFor")(function* (sku: string) {
  const client = yield* InventoryClient;
  const audit = yield* AuditSink;
  const result = yield* Effect.result(client.lookup(sku));
  if (result._tag === "Failure") {
    if (result.failure._tag === "InventoryHttpFailure" && result.failure.status === 404) {
      return { state: "unknown" as const };
    }
    yield* audit.record(result.failure);
    return { state: "unknown" as const };
  }
  return { state: "known" as const, units: result.success };
});

